func:
// Garde les derniers coils lus ; le décodage les utilisera.
flow.set('coils', msg.payload);
return null;

// Garde les derniers phaseurs lus (registres 80 à 159) ; le décodage les utilisera.
flow.set('phaseurs', msg.payload);
return null;

// Transforme les valeurs Modbus brutes en un objet "etat" lisible par l'IHM.
// Sorties : 1 = état complet (pages), 2 = courbe I, 3 = courbe Io
const a = global.get('adr');
const co = flow.get('coils');
const hr = msg.payload;
const ph = flow.get('phaseurs') || [];
if (!a || !co) return null;

const adr = (bloc, decalage) => a.BLOC * bloc + decalage;
const t = new Date();
const heure = t.toLocaleTimeString('fr-FR') + '.' + String(t.getMilliseconds()).padStart(3, '0');
const NATURES = ['permanent', 'fugitif', 'semi-permanent'];
const ETAPES = ['repos', 'temps mort RR', 'récupération RR', 'temps mort RL', 'récupération RL', 'DÉFINITIF'];

function libellePhases(bits) {
    const p = [];
    if (bits & 1) p.push('L1');
    if (bits & 2) p.push('L2');
    if (bits & 4) p.push('L3');
    if (bits & 8) p.push('Terre');
    return p.length ? p.join('-') : '-';
}
function libelleProtection(origine) {
    const p = [];
    if (origine & 1) p.push('I>');
    if (origine & 2) p.push('Io>');
    if (origine & 4) p.push('SLP');
    return p.length ? p.join(' + ') : '-';
}

// Lecture d'une cellule (bloc 0 = arrivée, 1 à 3 = départs)
function cellule(bloc, nom) {
    const i = adr(bloc, a.HR_I_L1);
    const r = adr(bloc, a.HR_REGLAGE_SEUIL_PHASE);
    const m = adr(bloc, a.HR_TEMPS_PROTECTION);
    const c = {
        bloc: bloc,
        nom: nom,
        ferme: co[adr(bloc, a.CO_POSITION_DJ)],
        courants: [hr[i], hr[i + 1], hr[i + 2]],
        io: hr[adr(bloc, a.HR_IO)],
        demPhase: co[adr(bloc, a.CO_DEMARRAGE_PHASE)],
        demTerre: co[adr(bloc, a.CO_DEMARRAGE_TERRE)],
        declPhase: co[adr(bloc, a.CO_DECLENCHEMENT_PHASE)],
        declTerre: co[adr(bloc, a.CO_DECLENCHEMENT_TERRE)],
        reglages: { seuilPhase: hr[r], tempoPhase: hr[r + 1], seuilTerre: hr[r + 2], tempoTerre: hr[r + 3] },
        releve: {
            tProt: hr[m], tOuv: hr[m + 1], tElim: hr[m + 2], phases: hr[m + 3], nb: hr[m + 4],
            origine: hr[adr(bloc, a.HR_ORIGINE_DECLENCHEMENT)],
        },
        defautInjecte: hr[adr(bloc, a.HR_DEFAUT_INJECTE)],
        natureDefaut: hr[adr(bloc, a.HR_NATURE_DEFAUT)],
    };
    if (bloc === 0) {
        c.declSlp = co[adr(0, a.CO_DECLENCHEMENT_SLP)];
        c.reglages.tempoSlp = hr[r + 4];
    } else {
        c.reglages.rrl = hr[r + 4];
        c.etapeRrl = hr[adr(bloc, a.HR_ETAPE_RRL)];
        c.resultatRrl = hr[adr(bloc, a.HR_RESULTAT_RRL)];
    }
    // Angles (degrés) pour les diagrammes de Fresnel.
    // La lecture des phaseurs commence à l'adresse 80 : ph[0] = adresse 80.
    const g = adr(bloc, a.PH_ANGLE_I_L1);
    c.anglesI = [ph[g] || 0, ph[g + 1] || 0, ph[g + 2] || 0];
    c.angleIo = ph[adr(bloc, a.PH_ANGLE_IO)] || 0;
    return c;
}

const etat = {
    heure: heure,
    tension: hr[adr(0, a.HR_TENSION_BARRE)] / a.ECHELLE_TENSION,
    alarme: co[adr(0, a.CO_VOYANT_ALARME)],
    modeAleatoire: co[adr(0, a.CO_MODE_ALEATOIRE)],
    slpEnService: co[adr(0, a.CO_SLP_EN_SERVICE)],
    dureeCycle: hr[adr(0, a.HR_DUREE_CYCLE)],
    arrivee: cellule(0, 'Arrivée'),
    departs: [1, 2, 3].map(b => cellule(b, 'Départ ' + b)),
};
etat.arrivee.verrouille = etat.arrivee.declPhase || etat.arrivee.declTerre || etat.arrivee.declSlp;
etat.departs.forEach(d => { d.verrouille = d.etapeRrl === 5; });

// Tensions simples du jeu de barres (module en kV, angle en degrés) et V0
const zv = adr(0, a.PH_V1);        // indices dans ph (ph[0] = adresse 80)
const za = adr(0, a.PH_ANGLE_V1);
etat.tensionsSimples = [0, 1, 2, 3].map(k => ({
    m: (ph[zv + k] || 0) / a.ECHELLE_TENSION_SIMPLE,
    a: ph[za + k] || 0,
}));

// Mot de vie : si le compteur de l'automate ne bouge plus, son cycle est arrêté.
const vie = hr[adr(0, a.HR_MOT_DE_VIE)];
etat.automateEnLigne = vie !== context.get('vie');
context.set('vie', vie);

// ---------------- Journal des événements (changements d'état) ----------------
const journal = flow.get('journal') || [];
function noter(texte, niveau) { journal.unshift({ heure: heure, texte: texte, niveau: niveau }); }

const avant = context.get('avant');
if (avant) {
    if (etat.modeAleatoire !== avant.modeAleatoire) noter('Mode aléatoire ' + (etat.modeAleatoire ? 'EN MARCHE' : 'arrêté'), 'test');
    if (etat.slpEnService !== avant.slpEnService) noter('Sélectivité logique (SLP) ' + (etat.slpEnService ? 'en service' : 'HORS SERVICE'), 'info');
    [etat.arrivee].concat(etat.departs).forEach((c, i) => {
        const p = i === 0 ? avant.arrivee : avant.departs[i - 1];
        const lieu = i === 0 ? 'Jeu de barres' : c.nom;
        // Banc de test ou mode aléatoire : apparition / disparition d'un défaut
        if (c.defautInjecte !== p.defautInjecte) {
            if (c.defautInjecte) noter(lieu + ' : défaut ' + libellePhases(c.defautInjecte) + ' ' + NATURES[c.natureDefaut] + ' apparu', 'test');
            else noter(lieu + ' : défaut disparu (' + NATURES[p.natureDefaut] + ')', 'test');
        }
        // Dans l'ordre chronologique : démarrage, déclenchement, puis manoeuvre du DJ
        if (c.demPhase && !p.demPhase) noter(c.nom + ' : démarrage I>', 'alerte');
        if (c.demTerre && !p.demTerre) noter(c.nom + ' : démarrage Io>', 'alerte');
        if (c.releve.nb !== p.releve.nb) {
            const slp = i === 0 && (c.releve.origine & 4);
            noter(c.nom + ' : DÉCLENCHEMENT ' + libelleProtection(c.releve.origine)
                  + (slp ? ' (défaut jeu de barres, déclenchement accéléré)' : ''), 'alarme');
        }
        if (c.ferme !== p.ferme) noter(c.nom + ' : disjoncteur ' + (c.ferme ? 'FERMÉ' : 'OUVERT'), 'info');
        // Réenclencheur
        if (i > 0 && c.etapeRrl !== p.etapeRrl) {
            if (c.etapeRrl === 1) noter(c.nom + ' : cycle de réenclenchement lancé, temps mort RR', 'alerte');
            if (c.etapeRrl === 2) noter(c.nom + ' : réenclenchement rapide (RR)', 'info');
            if (c.etapeRrl === 3) noter(c.nom + ' : défaut toujours présent après RR, temps mort RL', 'alerte');
            if (c.etapeRrl === 4) noter(c.nom + ' : réenclenchement lent (RL)', 'info');
            if (c.etapeRrl === 5) noter(c.nom + ' : DÉCLENCHEMENT DÉFINITIF (défaut permanent)', 'alarme');
            if (c.etapeRrl === 0 && p.etapeRrl === 5) noter(c.nom + ' : déclenchement définitif acquitté', 'info');
            if (c.etapeRrl === 0 && (p.etapeRrl === 2 || p.etapeRrl === 4)) {
                noter(c.nom + ' : cycle réussi, défaut éliminé par le ' + (p.etapeRrl === 2 ? 'RR (fugitif)' : 'RL (semi-permanent)'), 'ok');
            }
        }
        if (i === 0 && p.verrouille && !c.verrouille) noter('Arrivée : alarmes acquittées', 'info');
        const r = c.reglages, q = p.reglages;
        if (r.seuilPhase !== q.seuilPhase || r.tempoPhase !== q.tempoPhase || r.seuilTerre !== q.seuilTerre
            || r.tempoTerre !== q.tempoTerre || r.rrl !== q.rrl || r.tempoSlp !== q.tempoSlp) {
            noter(c.nom + ' : nouveaux réglages I> ' + r.seuilPhase + ' A / ' + r.tempoPhase + ' ms, Io> '
                  + r.seuilTerre + ' A / ' + r.tempoTerre + ' ms'
                  + (i === 0 ? ', SLP ' + r.tempoSlp + ' ms' : ', RRL ' + (r.rrl ? 'en service' : 'hors service')), 'info');
        }
    });
}
journal.splice(300);  // on garde les 300 derniers événements
flow.set('journal', journal);

// ---------------- Historique des relevés de temporisation ----------------
// Un enregistrement par déclenchement, dès que le DJ est ouvert (t élimination connu).
const historique = flow.get('historique') || [];
const dejaNotes = context.get('dejaNotes') || [null, null, null, null];
[etat.arrivee].concat(etat.departs).forEach((c, i) => {
    const r = c.releve;
    if (dejaNotes[i] === null) { dejaNotes[i] = r.nb; return; }  // au démarrage de l'IHM
    if (r.nb !== dejaNotes[i] && r.tElim > 0) {
        let reglage = (r.origine & 1) ? c.reglages.tempoPhase : c.reglages.tempoTerre;
        if (i === 0 && (r.origine & 4)) reglage = c.reglages.tempoSlp;
        let suite = '-';
        if (i === 0) suite = 'verrouillé';
        else if (c.etapeRrl === 1) suite = 'vers RR';
        else if (c.etapeRrl === 3) suite = 'vers RL';
        else if (c.etapeRrl === 5) suite = 'définitif';
        historique.unshift({
            heure: heure,
            depart: c.nom,
            phases: libellePhases(r.phases),
            protection: libelleProtection(r.origine),
            reglage: reglage,
            tProt: r.tProt,
            ecart: r.tProt - reglage,
            tOuv: r.tOuv,
            tElim: r.tElim,
            suite: suite,
        });
        noter(c.nom + ' : relevé t protection ' + r.tProt + ' ms, t ouverture DJ ' + r.tOuv + ' ms, t élimination ' + r.tElim + ' ms', 'info');
        dejaNotes[i] = r.nb;
    }
});
historique.splice(500);
context.set('dejaNotes', dejaNotes);
flow.set('historique', historique);

context.set('avant', JSON.parse(JSON.stringify(etat)));
etat.journal = journal.slice(0, 100);
etat.historique = historique;

// Courbes : un message par départ (topic = nom de la courbe)
const courbeI = etat.departs.map(d => ({ topic: d.nom, payload: Math.max(...d.courants) }));
const courbeIo = etat.departs.map(d => ({ topic: d.nom, payload: d.io }));

return [{ payload: etat }, courbeI, courbeIo];

// Transforme une commande de l'IHM en écriture(s) Modbus dans l'automate.
// msg.payload = { commande, bloc, valeur(s) }  (bloc 0 = arrivée / jeu de barres, 1 à 3 = départs)
const a = global.get('adr');
const c = msg.payload;
const adr = (bloc, decalage) => a.BLOC * bloc + decalage;
const entier = v => Math.max(0, Math.min(65535, Math.round(Number(v) || 0)));
const ecrire = (fc, address, value, quantity) => ({ payload: { fc: fc, address: address, value: value, quantity: quantity || 1, unitid: 1 } });

// Commandes internes à l'IHM (pas de Modbus)
if (c.commande === 'effacerJournal') { flow.set('journal', []); return null; }
if (c.commande === 'effacerHistorique') { flow.set('historique', []); return null; }

// fc 5 = écrire 1 coil, fc 6 = écrire 1 registre, fc 16 = écrire plusieurs registres
switch (c.commande) {
    case 'ouvrir':
        return ecrire(5, adr(c.bloc, a.CO_ACR_OUVERTURE), true);
    case 'fermer':
        return ecrire(5, adr(c.bloc, a.CO_ACR_FERMETURE), true);
    case 'acquitter':
        return ecrire(5, adr(0, a.CO_ACR_ACQUITTEMENT), true);
    case 'slp':
        return ecrire(5, adr(0, a.CO_SLP_EN_SERVICE), !!c.valeur);
    case 'aleatoire':
        return ecrire(5, adr(0, a.CO_MODE_ALEATOIRE), !!c.valeur);
    case 'defaut':
        // La nature d'abord, puis les bits : la simulation réagit au changement des bits
        return [[ecrire(6, adr(c.bloc, a.HR_NATURE_DEFAUT), entier(c.nature)),
                 ecrire(6, adr(c.bloc, a.HR_DEFAUT_INJECTE), entier(c.valeur))]];
    case 'reglages':
        // 5 registres : seuil I>, tempo I>, seuil Io>, tempo Io>, RRL (départ) ou tempo SLP (arrivée)
        return ecrire(16, adr(c.bloc, a.HR_REGLAGE_SEUIL_PHASE), c.valeurs.map(entier), 5);
    default:
        return null;
}
